INSERT INTO t_countmin_stats_string_{materialize}
SELECT c1, c2, c3, c4, c5 FROM t_countmin_string_stats_src
SETTINGS materialize_statistics_on_insert = {materialize}

INSERT INTO t_countmin_stats_low_cardinality_{materialize}
SELECT c1, c6, c7, c8, c9 FROM t_countmin_string_stats_src
SETTINGS materialize_statistics_on_insert = {materialize}

INSERT INTO t_countmin_stats_numeric_{materialize}
SELECT c1, c2, c3 FROM t_countmin_numeric_stats_src
SETTINGS materialize_statistics_on_insert = {materialize}

INSERT INTO t_countmin_stats_low_cardinality_numeric_{materialize}
SELECT c1, c4, c5 FROM t_countmin_numeric_stats_src
SETTINGS materialize_statistics_on_insert = {materialize}

INSERT INTO t_countmin_stats_nullable_string_{materialize}
SELECT c1, c2 FROM t_countmin_nullable_string_stats_src
SETTINGS materialize_statistics_on_insert = {materialize}

INSERT INTO t_countmin_stats_low_cardinality_nullable_string_{materialize}
SELECT c1, c3 FROM t_countmin_nullable_string_stats_src
SETTINGS materialize_statistics_on_insert = {materialize}

INSERT INTO t_countmin_stats_low_cardinality_large_dictionary_{materialize}
SELECT c1, c2 FROM t_countmin_large_dictionary_stats_src WHERE c1 >= 990000
SETTINGS materialize_statistics_on_insert = {materialize}
